<?php
$escape = static fn ($value) => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$errors = [
    'empty_fields' => 'Complete all password fields.',
    'password_mismatch' => 'The new passwords do not match.',
    'wrong_current_password' => 'The current password is incorrect.',
    'password_too_short' => 'Use at least eight characters for your new password.',
    'invalid_profile' => 'Check the name, phone, address, and city lengths.',
];
$error = $errors[$_GET['error'] ?? ''] ?? '';
$success = ($_GET['success'] ?? '') === 'password_updated' ? 'Password updated.' : (($_GET['success'] ?? '') === '1' ? 'Profile updated.' : '');
?>
<section class="section-wrap dashboard-page"><div class="dashboard-heading"><div><p class="eyebrow">YOUR SHIFA SPACE</p><h1>Your details<span class="brand-dot">.</span></h1><p>Keep your delivery details close and up to date.</p></div></div><div class="account-tabs"><a href="<?= $escape($base) ?>/account/orders">Orders</a><a href="<?= $escape($base) ?>/profile" class="active">Profile</a></div><?php if ($error !== ''): ?><p class="form-error" role="alert"><?= $escape($error) ?></p><?php endif; ?><?php if ($success !== ''): ?><p class="profile-success" role="status"><?= $escape($success) ?></p><?php endif; ?><div class="profile-grid"><section class="data-card"><p class="eyebrow">CONTACT DETAILS</p><h2 class="profile-title"><?= $escape($profile['name']) ?></h2><p class="profile-email"><?= $escape($profile['email']) ?></p><?php if ($isOwner): ?><form class="admin-form profile-form" method="post" action="<?= $escape($base) ?>/profile/update"><input type="hidden" name="csrf_token" value="<?= $escape($_SESSION['profile_csrf']) ?>"><label>Name<input name="name" maxlength="100" required value="<?= $escape($profile['name']) ?>"></label><label>Phone<input name="phone" maxlength="30" value="<?= $escape($profile['phone'] ?? '') ?>"></label><label>Address<input name="address" maxlength="255" value="<?= $escape($profile['address'] ?? '') ?>"></label><label>City<input name="city" maxlength="80" value="<?= $escape($profile['city'] ?? '') ?>"></label><button class="button button-dark">Save your details ↗</button></form><?php endif; ?></section><?php if ($isOwner && !empty($profile['password_hash'])): ?><section class="data-card"><p class="eyebrow">ACCOUNT SECURITY</p><h2 class="profile-title">Change password</h2><form class="admin-form profile-form" method="post" action="<?= $escape($base) ?>/profile/password"><input type="hidden" name="csrf_token" value="<?= $escape($_SESSION['profile_csrf']) ?>"><label>Current password<input type="password" name="current_password" required autocomplete="current-password"></label><label>New password<input type="password" name="new_password" required minlength="8" autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" required minlength="8" autocomplete="new-password"></label><button class="button button-outline">Update password ↗</button></form></section><?php endif; ?></div></section>
